"""End-to-end bathymetric product pipeline.

Runs the full chain in one call: grid binning
(:mod:`ocean_sonar.grid`), terrain analysis
(:mod:`ocean_sonar.terrain`), quality assessment
(:mod:`ocean_sonar.quality`), substrate classification
(:mod:`ocean_sonar.substrate`), crosspoint evaluation
(:mod:`ocean_sonar.crosspoint`) and the combined verdict
(:mod:`ocean_sonar.report`).
"""

from __future__ import annotations

import json
import math

from . import crosspoint, grid, quality, report, substrate, terrain
from .report import (
    _check_crosspoint,
    _COUNT_KEYS,
    _overall_verdict,
    _to_jsonable,
)

__all__ = ["build", "serialize"]

_PRODUCT_KEYS = ("crosspoint", "layers", "overall")
_LAYER_KEYS = (
    "resolution",
    "nx",
    "ny",
    "cells",
    "analysis",
    "quality",
    "substrate",
)
_QUALITY_KEYS = (
    "resolution",
    "total",
    "valid",
    "coverage",
    "slope_exceed",
    "roughness_exceed",
)
_SUBSTRATE_KEYS = ("resolution", "nx", "ny", "classes", "counts")
_QUALITY_VALUES = ("pass", "fail")


def build(
    points,
    bounds,
    resolutions,
    crossings,
    tolerance=0.5,
    slope_limit=5.0,
    roughness_limit=1.0,
):
    """Build the full gridded terrain product in one pipeline.

    The stages run strictly in this order, exactly once each and with
    no interleaving, and every exception from any stage short-circuits
    and is propagated unchanged:

    1. :func:`grid.build(points, bounds, resolutions)
       <ocean_sonar.grid.build>` bins the soundings into one grid per
       resolution; each layer is ``(resolution, nx, ny, cells)``.
    2. The grids are passed unchanged to
       :func:`terrain.analyze_layers <ocean_sonar.terrain.analyze_layers>`.
    3. From every analysis dict the tuple
       ``(resolution, nx, ny, analysis)`` is fed, in layer order, to
       :func:`quality.assess <ocean_sonar.quality.assess>` and
       :func:`substrate.classify <ocean_sonar.substrate.classify>`
       together with ``slope_limit`` and ``roughness_limit``.
    4. :func:`crosspoint.evaluate <ocean_sonar.crosspoint.evaluate>` is
       called with ``crossings`` and ``tolerance``.
    5. The crosspoint, quality and substrate results are passed
       unchanged to :func:`report.summarize
       <ocean_sonar.report.summarize>`, whose ``overall`` verdict is
       used.

    The validation and first-error order is therefore that of
    :func:`~ocean_sonar.grid.build` (points, bounds, resolutions),
    then :func:`~ocean_sonar.terrain.analyze_layers`, then
    :func:`~ocean_sonar.quality.assess` (layers, ``slope_limit``,
    ``roughness_limit``), then :func:`~ocean_sonar.substrate.classify`,
    then :func:`~ocean_sonar.crosspoint.evaluate` (``crossings``,
    ``tolerance``), then :func:`~ocean_sonar.report.summarize`. All
    numeric types, rounding (six decimals, negative zero normalized)
    and key orders are exactly those produced by the underlying
    functions. Inputs are not modified.

    Returns a dict with keys in the order
    ``crosspoint, layers, overall``: ``crosspoint`` is the dict
    returned by :func:`~ocean_sonar.crosspoint.evaluate`, ``layers`` is
    a tuple with one dict per resolution and ``overall`` is the
    :func:`~ocean_sonar.report.summarize` verdict (``"pass"`` or
    ``"fail"``). Each layer dict has keys in the order
    ``resolution, nx, ny, cells, analysis, quality, substrate``:
    ``resolution``, ``nx``, ``ny`` and ``cells`` come from the
    corresponding :func:`~ocean_sonar.grid.build` layer, ``analysis``
    is the tuple from :func:`~ocean_sonar.terrain.analyze_layers`, and
    ``quality``/``substrate`` are the matching items returned by
    :func:`~ocean_sonar.quality.assess` and
    :func:`~ocean_sonar.substrate.classify`.
    """
    grids = grid.build(points, bounds, resolutions)
    analyzed = terrain.analyze_layers(grids)

    assess_layers = tuple(
        (item["resolution"], item["nx"], item["ny"], item["analysis"])
        for item in analyzed
    )
    qualities = quality.assess(
        assess_layers, slope_limit, roughness_limit
    )
    substrates = substrate.classify(
        assess_layers, slope_limit, roughness_limit
    )

    crosspoint_result = crosspoint.evaluate(crossings, tolerance)
    overall = report.summarize(
        crosspoint_result, qualities, substrates
    )["overall"]

    layers = tuple(
        {
            "resolution": analyzed[i]["resolution"],
            "nx": analyzed[i]["nx"],
            "ny": analyzed[i]["ny"],
            "cells": grids[i][3],
            "analysis": analyzed[i]["analysis"],
            "quality": qualities[i],
            "substrate": substrates[i],
        }
        for i in range(len(grids))
    )

    return {
        "crosspoint": crosspoint_result,
        "layers": layers,
        "overall": overall,
    }


def _check_cells(index, cells, nx, ny):
    if not isinstance(cells, tuple):
        raise TypeError(f"layers[{index}].cells must be a tuple")
    if len(cells) != nx * ny:
        raise ValueError(
            f"layers[{index}].cells must have nx * ny elements"
        )
    for j in range(len(cells)):
        prefix = f"layers[{index}].cells[{j}]: "
        cell = cells[j]
        if not isinstance(cell, tuple):
            raise TypeError(prefix + "must be a tuple")
        if len(cell) != 2:
            raise ValueError(prefix + "must have 2 elements")
        count, mean = cell
        if type(count) is not int:
            raise TypeError(prefix + "count must be a non-bool int")
        if not count >= 0:
            raise ValueError(prefix + "count must be >= 0")
        if count == 0:
            if mean is not None:
                raise ValueError(prefix + "mean must be None when count is 0")
        else:
            if type(mean) is not float:
                raise TypeError(prefix + "mean must be a float")
            if not math.isfinite(mean):
                raise ValueError(prefix + "mean must be finite")
            if not mean >= 0:
                raise ValueError(prefix + "mean must be >= 0")


def _check_analysis(index, analysis, nx, ny):
    if not isinstance(analysis, tuple):
        raise TypeError(f"layers[{index}].analysis must be a tuple")
    if len(analysis) != nx * ny:
        raise ValueError(
            f"layers[{index}].analysis must have nx * ny elements"
        )
    for j in range(len(analysis)):
        prefix = f"layers[{index}].analysis[{j}]: "
        cell = analysis[j]
        if not isinstance(cell, tuple):
            raise TypeError(prefix + "must be a tuple")
        if len(cell) != 2:
            raise ValueError(prefix + "must have 2 elements")
        slope, roughness = cell
        if slope is not None:
            if type(slope) is not float:
                raise TypeError(prefix + "slope must be a float")
            if not math.isfinite(slope):
                raise ValueError(prefix + "slope must be finite")
            if not slope >= 0:
                raise ValueError(prefix + "slope must be >= 0")
        if roughness is None:
            if slope is not None:
                raise ValueError(
                    prefix
                    + "roughness must not be None when slope is not None"
                )
        else:
            if type(roughness) is not float:
                raise TypeError(prefix + "roughness must be a float")
            if not math.isfinite(roughness):
                raise ValueError(prefix + "roughness must be finite")
            if not roughness >= 0:
                raise ValueError(prefix + "roughness must be >= 0")


def _check_quality(index, item):
    prefix = f"layers[{index}].quality: "
    if not isinstance(item, dict):
        raise TypeError(prefix + "must be a dict")
    if list(item.keys()) != list(_QUALITY_KEYS):
        raise TypeError(
            prefix
            + "keys must be in the order resolution, total, valid, "
            "coverage, slope_exceed, roughness_exceed"
        )

    resolution = item["resolution"]
    if type(resolution) is not float:
        raise TypeError(prefix + "resolution must be a float")
    if not math.isfinite(resolution):
        raise ValueError(prefix + "resolution must be finite")
    if resolution < 0:
        raise ValueError(prefix + "resolution must be >= 0")

    total = item["total"]
    if type(total) is not int:
        raise TypeError(prefix + "total must be a non-bool int")
    if not total > 0:
        raise ValueError(prefix + "total must be > 0")

    valid = item["valid"]
    if type(valid) is not int:
        raise TypeError(prefix + "valid must be a non-bool int")
    if not 0 <= valid <= total:
        raise ValueError(prefix + "valid must be in [0, total]")

    coverage = item["coverage"]
    if type(coverage) is not float:
        raise TypeError(prefix + "coverage must be a float")
    if not math.isfinite(coverage):
        raise ValueError(prefix + "coverage must be finite")
    if not 0 <= coverage <= 1:
        raise ValueError(prefix + "coverage must be in [0, 1]")

    for name in ("slope_exceed", "roughness_exceed"):
        value = item[name]
        if type(value) is not int:
            raise TypeError(prefix + f"{name} must be a non-bool int")
        if not 0 <= value <= total:
            raise ValueError(prefix + f"{name} must be in [0, total]")


def _check_substrate(index, item):
    prefix = f"layers[{index}].substrate: "
    if not isinstance(item, dict):
        raise TypeError(prefix + "must be a dict")
    if list(item.keys()) != list(_SUBSTRATE_KEYS):
        raise TypeError(
            prefix + "keys must be in the order resolution, nx, ny, classes, counts"
        )

    resolution = item["resolution"]
    if type(resolution) is not float:
        raise TypeError(prefix + "resolution must be a float")
    if not math.isfinite(resolution):
        raise ValueError(prefix + "resolution must be finite")
    if resolution < 0:
        raise ValueError(prefix + "resolution must be >= 0")

    nx = item["nx"]
    if type(nx) is not int:
        raise TypeError(prefix + "nx must be a non-bool int")
    if not nx > 0:
        raise ValueError(prefix + "nx must be > 0")

    ny = item["ny"]
    if type(ny) is not int:
        raise TypeError(prefix + "ny must be a non-bool int")
    if not ny > 0:
        raise ValueError(prefix + "ny must be > 0")

    classes = item["classes"]
    if not isinstance(classes, tuple):
        raise TypeError(prefix + "classes must be a tuple")
    if len(classes) != nx * ny:
        raise ValueError(prefix + "classes must have nx * ny elements")
    for j in range(len(classes)):
        cell_prefix = f"layers[{index}].substrate.classes[{j}]: "
        name = classes[j]
        if type(name) is not str:
            raise TypeError(cell_prefix + "must be a str")
        if name not in _COUNT_KEYS:
            raise ValueError(cell_prefix + f"unknown class {name!r}")

    counts = item["counts"]
    if not isinstance(counts, dict):
        raise TypeError(prefix + "counts must be a dict")
    if list(counts.keys()) != list(_COUNT_KEYS):
        raise TypeError(
            prefix + "counts keys must be in the order unknown, mud, sand, gravel, rock"
        )
    for name in _COUNT_KEYS:
        value = counts[name]
        if type(value) is not int:
            raise TypeError(prefix + f"counts.{name} must be a non-bool int")
        if value < 0:
            raise ValueError(prefix + f"counts.{name} must be >= 0")
        if value != classes.count(name):
            raise ValueError(prefix + f"counts.{name} must match classes")


def _check_layer(index, layer):
    prefix = f"layers[{index}]: "
    if not isinstance(layer, dict):
        raise TypeError(prefix + "must be a dict")
    if list(layer.keys()) != list(_LAYER_KEYS):
        raise TypeError(
            prefix
            + "keys must be in the order resolution, nx, ny, cells, "
            "analysis, quality, substrate"
        )

    resolution = layer["resolution"]
    if type(resolution) is not float:
        raise TypeError(prefix + "resolution must be a float")
    if not math.isfinite(resolution):
        raise ValueError(prefix + "resolution must be finite")
    if not resolution > 0:
        raise ValueError(prefix + "resolution must be > 0")

    nx = layer["nx"]
    if type(nx) is not int:
        raise TypeError(prefix + "nx must be a non-bool int")
    if not nx > 0:
        raise ValueError(prefix + "nx must be > 0")

    ny = layer["ny"]
    if type(ny) is not int:
        raise TypeError(prefix + "ny must be a non-bool int")
    if not ny > 0:
        raise ValueError(prefix + "ny must be > 0")

    _check_cells(index, layer["cells"], nx, ny)
    _check_analysis(index, layer["analysis"], nx, ny)

    quality_item = layer["quality"]
    _check_quality(index, quality_item)
    if quality_item["resolution"] != resolution:
        raise ValueError(
            prefix + "quality resolution must match layer resolution"
        )
    if quality_item["total"] != nx * ny:
        raise ValueError(prefix + "quality total must be nx * ny")

    substrate_item = layer["substrate"]
    _check_substrate(index, substrate_item)
    if substrate_item["resolution"] != resolution:
        raise ValueError(
            prefix + "substrate resolution must match layer resolution"
        )
    if substrate_item["nx"] != nx or substrate_item["ny"] != ny:
        raise ValueError(prefix + "substrate nx/ny must match layer nx/ny")


def serialize(product):
    """Serialize a :func:`build` result dict to UTF-8 JSON bytes.

    ``product`` must be the dict returned by :func:`build`, with keys
    exactly in the order ``crosspoint, layers, overall``:
    ``crosspoint`` is the dict returned by
    :func:`ocean_sonar.crosspoint.evaluate` (keys
    ``count, bias, rmse, max_abs, within_tolerance, quality``);
    ``layers`` is a non-empty tuple with one dict per resolution and
    ``overall`` is ``"pass"`` or ``"fail"``. Each layer dict has keys
    exactly in the order
    ``resolution, nx, ny, cells, analysis, quality, substrate``:
    ``resolution`` a finite float ``> 0``; ``nx``/``ny`` non-bool
    positive ints; ``cells`` and ``analysis`` tuples of length
    ``nx * ny`` whose items are the ``(count, mean)`` and
    ``(slope, roughness)`` tuples produced by
    :func:`ocean_sonar.grid.build` and
    :func:`ocean_sonar.terrain.analyze` — empty cells are
    ``(0, None)``/``(None, None)`` and boundary cells may also be
    ``(None, roughness)`` —; ``quality`` and ``substrate`` are
    the matching items returned by :func:`ocean_sonar.quality.assess`
    and :func:`ocean_sonar.substrate.classify`. ``overall`` is
    recomputed with the :func:`ocean_sonar.report.summarize` rule from
    ``crosspoint`` and the per-layer ``quality``/``substrate`` values.

    Validation order, stopping at the first error: the top-level
    container and key order, then ``crosspoint``, then the layers tuple
    and each layer in index order — per layer its container, key order
    and ``resolution``/``nx``/``ny``, then ``cells``, then
    ``analysis``, then ``quality``, then ``substrate`` — and finally
    ``overall``. Container, key-order and field-type errors raise
    ``TypeError``; length, finiteness, range, consistency and enum
    errors (including an ``overall`` that disagrees with the recomputed
    verdict) raise ``ValueError``. The input is not modified.

    On success the product is encoded as UTF-8 JSON with the key order
    preserved, ``ensure_ascii=False``, ``separators=(",", ":")``,
    ``allow_nan=False``, no indentation and no trailing newline.
    Floats are first rounded with ``round(float(v), 6)`` and negative
    zero is normalized to ``0.0``; tuples are recursively converted to
    arrays. Any JSON or UTF-8 encoding failure raises ``ValueError``.

    Returns the JSON document as ``bytes``.
    """
    if not isinstance(product, dict):
        raise TypeError("product must be a dict")
    if list(product.keys()) != list(_PRODUCT_KEYS):
        raise TypeError(
            "product keys must be in the order crosspoint, layers, overall"
        )

    crosspoint_result = product["crosspoint"]
    layers = product["layers"]
    _check_crosspoint(crosspoint_result)

    if not isinstance(layers, tuple):
        raise TypeError("layers must be a tuple")
    if len(layers) == 0:
        raise ValueError("layers must be non-empty")

    for i in range(len(layers)):
        _check_layer(i, layers[i])

    overall = product["overall"]
    if type(overall) is not str:
        raise TypeError("overall must be a str")
    if overall not in _QUALITY_VALUES:
        raise ValueError("overall must be 'pass' or 'fail'")

    terrain = tuple(layer["quality"] for layer in layers)
    substrates = tuple(layer["substrate"] for layer in layers)
    recomputed = _overall_verdict(crosspoint_result, terrain, substrates)
    if overall != recomputed:
        raise ValueError(
            "overall is inconsistent with crosspoint, layers and substrate"
        )

    try:
        text = json.dumps(
            _to_jsonable(product),
            ensure_ascii=False,
            separators=(",", ":"),
            allow_nan=False,
        )
        return text.encode("utf-8")
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError(
            f"product: could not be serialized to JSON: {exc}"
        ) from exc

"""Quality assessment of gridded terrain-analysis layers.

Given per-layer ``(r, nx, ny, analysis)`` descriptions where each
analysis cell is a ``(slope, roughness)`` pair as produced by
:func:`ocean_sonar.terrain.analyze`, summarize coverage and the counts
of cells whose slope/roughness strictly exceed the given limits.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["assess"]


def _round6(value):
    result = round(float(value), 6)
    if result == 0:
        result = 0.0
    return result


def assess(layers, slope_limit=5.0, roughness_limit=1.0):
    """Assess coverage and limit exceedance per terrain layer.

    ``layers`` is a non-empty list/tuple of ``(r, nx, ny, analysis)``
    items: ``r`` is a finite non-bool int/float ``> 0``; ``nx``/``ny``
    are non-bool positive ints; ``analysis`` is a list/tuple of length
    ``nx * ny`` whose items are two-element list/tuples
    ``(slope, roughness)``. A cell is either exactly ``(None, None)``
    (empty), or ``slope`` is ``None`` or a finite non-bool int/float
    ``>= 0`` and ``roughness`` is a finite non-bool int/float ``>= 0``.
    ``slope_limit``/``roughness_limit`` are finite non-bool int/float
    values ``> 0``.

    Validation follows the signature parameter order, then layer and
    cell index order, then field order, stopping at the first error:
    type mismatches (including bool) raise ``TypeError``, all other
    constraint errors raise ``ValueError``. Layer errors are prefixed
    with ``"layers[i]: "`` and cell errors with
    ``"layers[i].analysis[j]: "``.

    Returns a tuple in the same order as ``layers``; each item is a
    dict with keys ``resolution, total, valid, coverage,
    slope_exceed, roughness_exceed``. ``total`` is ``nx * ny``,
    ``valid`` counts non-empty cells and ``coverage`` is
    ``valid / total``. Exceedance counts use strict ``>`` and ignore
    ``None``. Counts are ints; the other values are
    ``round(float(v), 6)`` (negative zero normalized to ``0.0``).
    Inputs are not modified.
    """
    if not isinstance(layers, (list, tuple)):
        raise TypeError("layers must be a list or tuple")
    if len(layers) == 0:
        raise ValueError("layers must be non-empty")

    for i in range(len(layers)):
        prefix = f"layers[{i}]: "
        layer = layers[i]
        if not isinstance(layer, (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(layer) != 4:
            raise ValueError(prefix + "must have 4 elements")
        r, nx, ny, analysis = layer

        if not _is_real_number(r):
            raise TypeError(prefix + "r must be a non-bool int or float")
        if not math.isfinite(r):
            raise ValueError(prefix + "r must be finite")
        if not r > 0:
            raise ValueError(prefix + "r must be > 0")

        for name, value in (("nx", nx), ("ny", ny)):
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(prefix + f"{name} must be a non-bool int")
            if not value > 0:
                raise ValueError(prefix + f"{name} must be > 0")

        if not isinstance(analysis, (list, tuple)):
            raise TypeError(prefix + "analysis must be a list or tuple")
        if len(analysis) != nx * ny:
            raise ValueError(prefix + "analysis must have nx * ny elements")

        for j in range(len(analysis)):
            cell_prefix = f"layers[{i}].analysis[{j}]: "
            cell = analysis[j]
            if not isinstance(cell, (list, tuple)):
                raise TypeError(cell_prefix + "must be a list or tuple")
            if len(cell) != 2:
                raise ValueError(cell_prefix + "must have 2 elements")
            slope, roughness = cell
            if slope is None and roughness is None:
                continue
            if slope is not None:
                if not _is_real_number(slope):
                    raise TypeError(
                        cell_prefix + "slope must be None or a non-bool int or float"
                    )
                if not math.isfinite(slope):
                    raise ValueError(cell_prefix + "slope must be finite")
                if not slope >= 0:
                    raise ValueError(cell_prefix + "slope must be >= 0")
            if not _is_real_number(roughness):
                raise TypeError(
                    cell_prefix + "roughness must be a non-bool int or float"
                )
            if not math.isfinite(roughness):
                raise ValueError(cell_prefix + "roughness must be finite")
            if not roughness >= 0:
                raise ValueError(cell_prefix + "roughness must be >= 0")

    for name, value in (("slope_limit", slope_limit), ("roughness_limit", roughness_limit)):
        if not _is_real_number(value):
            raise TypeError(f"{name} must be a non-bool int or float")
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
        if not value > 0:
            raise ValueError(f"{name} must be > 0")

    result = []
    for r, nx, ny, analysis in layers:
        total = nx * ny
        valid = 0
        slope_exceed = 0
        roughness_exceed = 0
        for slope, roughness in analysis:
            if slope is None and roughness is None:
                continue
            valid += 1
            if slope is not None and slope > slope_limit:
                slope_exceed += 1
            if roughness > roughness_limit:
                roughness_exceed += 1
        result.append(
            {
                "resolution": _round6(r),
                "total": total,
                "valid": valid,
                "coverage": _round6(valid / total),
                "slope_exceed": slope_exceed,
                "roughness_exceed": roughness_exceed,
            }
        )
    return tuple(result)

"""Seabed substrate classification from slope/roughness analysis grids.

Each layer pairs a regular per-cell ``(slope, roughness)`` analysis grid
(as produced by :func:`ocean_sonar.terrain.analyze`) with its cell size
and classifies every cell into a substrate class by thresholding slope
and roughness.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["classify"]

_CLASSES = ("mud", "sand", "gravel", "rock")


def _round6(value):
    result = round(float(value), 6)
    if result == 0:
        result = 0.0
    return result


def _check_limit(name, value):
    if not _is_real_number(value):
        raise TypeError(f"{name} must be a non-bool int or float")
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    if not value > 0:
        raise ValueError(f"{name} must be > 0")


def classify(layers, slope_limit=5.0, roughness_limit=1.0):
    """Classify analysis grids into seabed substrate classes.

    ``layers`` is a non-empty list/tuple of four-element list/tuples
    ``(r, nx, ny, analysis)``: ``r`` is the cell size, a finite non-bool
    int/float with ``r > 0``; ``nx``/``ny`` are non-bool positive ints;
    ``analysis`` is a list/tuple of length ``nx * ny`` ordered by ``y``
    then ``x``. Each cell is a two-element list/tuple ``(slope,
    roughness)``; ``(None, None)``, ``(None, q)`` and ``(p, q)`` are
    legal (``None`` marks unknown), ``(p, None)`` with non-``None``
    ``p`` is not. Non-``None`` values must be finite non-bool
    int/float ``>= 0``. ``slope_limit``/``roughness_limit`` are finite
    non-bool int/float ``> 0``.

    A cell with ``slope`` equal to ``None`` is ``unknown``. Otherwise
    the bit pair ``(slope > slope_limit, roughness > roughness_limit)``
    selects the class: ``00`` mud, ``01`` sand, ``10`` gravel,
    ``11`` rock.

    Validation order: ``layers`` container, non-emptiness, then per
    layer (container, 4 elements, ``r``, ``nx``, ``ny``, ``analysis``
    container/length), then per cell (container, 2 elements, ``slope``,
    ``roughness``), then ``slope_limit``, then ``roughness_limit``;
    checking stops at the first error. Type mismatches (including bool)
    raise ``TypeError``, all other constraint errors raise
    ``ValueError``. Layer errors are prefixed with ``"layers[i]: "``
    and cell errors with ``"layers[i].analysis[j]: "``.

    Returns a tuple with one dict per layer, keys in order
    ``resolution``, ``nx``, ``ny``, ``classes``, ``counts``.
    ``resolution`` is ``round(float(r), 6)`` (negative zero normalized
    to ``0.0``); ``classes`` is a tuple of class name strings in grid
    order (``y`` then ``x``); ``counts`` maps ``unknown``, ``mud``,
    ``sand``, ``gravel``, ``rock`` (in that key order) to int counts.
    Inputs are not modified.
    """
    if not isinstance(layers, (list, tuple)):
        raise TypeError("layers must be a list or tuple")
    if len(layers) == 0:
        raise ValueError("layers must be non-empty")

    for i in range(len(layers)):
        prefix = f"layers[{i}]: "
        layer = layers[i]
        if not isinstance(layer, (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(layer) != 4:
            raise ValueError(prefix + "must have 4 elements")
        r, nx, ny, analysis = layer
        if not _is_real_number(r):
            raise TypeError(prefix + "r must be a non-bool int or float")
        if not math.isfinite(r):
            raise ValueError(prefix + "r must be finite")
        if not r > 0:
            raise ValueError(prefix + "r must be > 0")
        for name, value in (("nx", nx), ("ny", ny)):
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(prefix + f"{name} must be a non-bool int")
            if not value > 0:
                raise ValueError(prefix + f"{name} must be > 0")
        if not isinstance(analysis, (list, tuple)):
            raise TypeError(prefix + "analysis must be a list or tuple")
        if len(analysis) != nx * ny:
            raise ValueError(prefix + "analysis must have nx * ny elements")
        for j in range(len(analysis)):
            cell_prefix = f"layers[{i}].analysis[{j}]: "
            cell = analysis[j]
            if not isinstance(cell, (list, tuple)):
                raise TypeError(cell_prefix + "must be a list or tuple")
            if len(cell) != 2:
                raise ValueError(cell_prefix + "must have 2 elements")
            slope, roughness = cell
            if slope is not None:
                if not _is_real_number(slope):
                    raise TypeError(
                        cell_prefix + "slope must be a non-bool int or float"
                    )
                if not math.isfinite(slope):
                    raise ValueError(cell_prefix + "slope must be finite")
                if not slope >= 0:
                    raise ValueError(cell_prefix + "slope must be >= 0")
            if roughness is None:
                if slope is not None:
                    raise ValueError(
                        cell_prefix
                        + "roughness must not be None when slope is not None"
                    )
            else:
                if not _is_real_number(roughness):
                    raise TypeError(
                        cell_prefix + "roughness must be a non-bool int or float"
                    )
                if not math.isfinite(roughness):
                    raise ValueError(cell_prefix + "roughness must be finite")
                if not roughness >= 0:
                    raise ValueError(cell_prefix + "roughness must be >= 0")

    _check_limit("slope_limit", slope_limit)
    _check_limit("roughness_limit", roughness_limit)

    result = []
    for layer in layers:
        r, nx, ny, analysis = layer
        classes = []
        counts = {"unknown": 0, "mud": 0, "sand": 0, "gravel": 0, "rock": 0}
        for cell in analysis:
            slope, roughness = cell
            if slope is None:
                name = "unknown"
            else:
                index = (
                    2 * (slope > slope_limit) + (roughness > roughness_limit)
                )
                name = _CLASSES[index]
            classes.append(name)
            counts[name] += 1
        result.append(
            {
                "resolution": _round6(r),
                "nx": nx,
                "ny": ny,
                "classes": tuple(classes),
                "counts": counts,
            }
        )
    return tuple(result)

"""Grid binning of sonar soundings at multiple resolutions.

For every resolution ``r`` the rectangle ``(xmin, ymin)``-
``(xmax, ymax)`` is divided into ``nx = (xmax - xmin) / r`` columns
and ``ny = (ymax - ymin) / r`` rows, both integral. A cell includes
its left/bottom edges and excludes its right/top edges; a point on the
maximum edge is assigned to the last column/row. Cells are ordered by
``y`` then ``x`` (``y`` primary), and the depths falling in each cell
are averaged with ``math.fsum`` in point input order.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["build"]

_FIELDS = ("x", "y", "d")


def build(points, bounds, resolutions):
    """Bin points into regular grids at several resolutions.

    ``points`` is a non-empty list/tuple of three-element lists/tuples
    ``(x, y, d)``; ``bounds`` is a four-element list/tuple
    ``(xmin, ymin, xmax, ymax)``; ``resolutions`` is a list/tuple of at
    least two strictly increasing values. Every value must be a finite
    non-bool int/float. In addition ``d >= 0``, ``xmin < xmax``,
    ``ymin < ymax`` and each resolution ``r > 0``; every point must lie
    within the closed bounds and both ``(xmax - xmin) / r`` and
    ``(ymax - ymin) / r`` must be integral Python floats.

    For each resolution ``r``, ``nx``/``ny`` are the two quotients as
    ints. Cells include the left/bottom edges and exclude the
    right/top edges, except that a point on the maximum edge joins the
    last column/row. Cells are expanded by ``y`` then ``x``; the depths
    of a cell are averaged as ``math.fsum`` over input order divided by
    their count.

    Validation order (first error wins): the three containers, point
    non-emptiness, each point (container, length), the bounds length,
    the resolutions minimum length, then the numeric types and
    finiteness of points/bounds/resolutions in that order; then
    ``d >= 0`` per point, ``xmin < xmax``, ``ymin < ymax``, the strict
    increase and positivity of resolutions, the closed-bounds
    containment per point, and finally per resolution the integral
    width/height quotients. Container and value type errors (including
    bool) raise ``TypeError``; all other constraint errors raise
    ``ValueError``. Point errors are prefixed with ``"points[i]: "``.

    Returns a tuple in resolutions order; each layer is
    ``(r, nx, ny, cells)`` and each cell is ``(count, mean)`` with empty
    cells fixed as ``(0, None)``. ``nx``/``ny``/``count`` are ints;
    ``r``/``mean`` are floats rounded to 6 decimals with
    ``round(float(v), 6)`` (negative zero normalized to ``0.0``). All
    binning uses the unrounded input values; inputs are not modified.
    """
    for name, value in (
        ("points", points),
        ("bounds", bounds),
        ("resolutions", resolutions),
    ):
        if not isinstance(value, (list, tuple)):
            raise TypeError(f"{name} must be a list or tuple")

    if len(points) == 0:
        raise ValueError("points must be non-empty")
    for i in range(len(points)):
        prefix = f"points[{i}]: "
        if not isinstance(points[i], (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(points[i]) != 3:
            raise ValueError(prefix + "must have 3 elements")
    if len(bounds) != 4:
        raise ValueError("bounds must have 4 elements")
    if len(resolutions) < 2:
        raise ValueError("resolutions must have at least 2 elements")

    for i in range(len(points)):
        prefix = f"points[{i}]: "
        for name, value in zip(_FIELDS, points[i]):
            if not _is_real_number(value):
                raise TypeError(prefix + f"{name} must be a non-bool int or float")
            if not math.isfinite(value):
                raise ValueError(prefix + f"{name} must be finite")
    for value in bounds:
        if not _is_real_number(value):
            raise TypeError("bounds elements must be non-bool int or float")
    for value in bounds:
        if not math.isfinite(value):
            raise ValueError("bounds elements must be finite")
    for value in resolutions:
        if not _is_real_number(value):
            raise TypeError("resolutions elements must be non-bool int or float")
    for value in resolutions:
        if not math.isfinite(value):
            raise ValueError("resolutions elements must be finite")

    for i in range(len(points)):
        if not points[i][2] >= 0:
            raise ValueError(f"points[{i}]: d must be >= 0")

    xmin, ymin, xmax, ymax = bounds
    if not xmin < xmax:
        raise ValueError("xmin must be < xmax")
    if not ymin < ymax:
        raise ValueError("ymin must be < ymax")

    for k in range(len(resolutions) - 1):
        if not resolutions[k] < resolutions[k + 1]:
            raise ValueError("resolutions must be strictly increasing")
    for k in range(len(resolutions)):
        if not resolutions[k] > 0:
            raise ValueError(f"resolutions[{k}] must be > 0")

    for i in range(len(points)):
        x, y, _ = points[i]
        if not (xmin <= x <= xmax and ymin <= y <= ymax):
            raise ValueError(f"points[{i}]: point must be within bounds")

    width = xmax - xmin
    height = ymax - ymin
    grids = []
    for k in range(len(resolutions)):
        r = resolutions[k]
        qx = width / r
        qy = height / r
        if not qx.is_integer():
            raise ValueError(f"width must be divisible by resolutions[{k}]")
        if not qy.is_integer():
            raise ValueError(f"height must be divisible by resolutions[{k}]")
        grids.append((r, int(qx), int(qy)))

    layers = []
    for r, nx, ny in grids:
        buckets = [[] for _ in range(ny * nx)]
        for x, y, d in points:
            ix = math.floor((x - xmin) / r)
            iy = math.floor((y - ymin) / r)
            if ix == nx:
                ix = nx - 1
            if iy == ny:
                iy = ny - 1
            buckets[iy * nx + ix].append(d)

        cells = []
        for bucket in buckets:
            count = len(bucket)
            if count == 0:
                cells.append((0, None))
                continue
            mean = round(float(math.fsum(bucket) / count), 6)
            if mean == 0:
                mean = 0.0
            cells.append((count, mean))

        rr = round(float(r), 6)
        if rr == 0:
            rr = 0.0
        layers.append((rr, nx, ny, tuple(cells)))
    return tuple(layers)

